<script lang="ts">import { onMount } from 'svelte';import {api} from '$lib/api';import type {Program,Session,Template} from '$lib/types';let programs:Program[]=[];let sessions:Session[]=[];let templates:Template[]=[];let error='';let notice='';let programName='';let template={programId:'',name:'',dayOfWeek:'Monday',startTime:'05:00 PM',durationMinutes:60,beltScope:''};let session={classTemplateId:'',sessionDateUtc:new Date().toISOString().slice(0,10),notes:''};async function load(){try{[programs,sessions]=await Promise.all([api<Program[]>('/api/programs'),api<Session[]>('/api/sessions')]);templates=programs.flatMap(x=>x.templates);}catch(e){error=e instanceof Error?e.message:'Could not load class data.';}}async function createProgram(){try{await api('/api/programs',{method:'POST',body:JSON.stringify({name:programName,description:'Managed in the Task Karate staff workspace.'})});programName='';notice='Program created.';await load();}catch(e){error=e instanceof Error?e.message:'Could not create program.';}}async function createTemplate(){try{await api('/api/class-templates',{method:'POST',body:JSON.stringify(template)});notice='Class template created.';await load();}catch(e){error=e instanceof Error?e.message:'Could not create template.';}}async function createSession(){try{await api('/api/sessions',{method:'POST',body:JSON.stringify({...session,sessionDateUtc:new Date(session.sessionDateUtc+'T00:00:00Z').toISOString()})});notice='Class session created.';await load();}catch(e){error=e instanceof Error?e.message:'Could not create session.';}}onMount(load);</script>
<div class="toolbar"><div><span class="eyebrow">CLASSES</span><h2>Programs and class sessions</h2></div></div>{#if error}<div class="error">{error}</div>{/if}{#if notice}<div class="status">{notice}</div>{/if}<div class="split"><section class="card"><h3>Program</h3><form on:submit|preventDefault={createProgram} class="form-grid"><label class="full">Program name<input bind:value={programName} required /></label><div class="full"><button class="button">Create program</button></div></form><h3>Class template</h3><form on:submit|preventDefault={createTemplate} class="form-grid"><label class="full">Program<select bind:value={template.programId} required><option value="" disabled>Select program</option>{#each programs as program}<option value={program.id}>{program.name}</option>{/each}</select></label><label class="full">Template name<input bind:value={template.name} required /></label><label>Day<select bind:value={template.dayOfWeek}>{#each ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] as day}<option>{day}</option>{/each}</select></label><label>Start time<input bind:value={template.startTime} required /></label><label>Duration (minutes)<input type="number" min="1" max="480" bind:value={template.durationMinutes} required /></label><label>Belt scope<input bind:value={template.beltScope} /></label><div class="full"><button class="button">Create template</button></div></form></section><section class="card"><h3>Create dated session</h3><form on:submit|preventDefault={createSession} class="form-grid"><label class="full">Template<select bind:value={session.classTemplateId} required><option value="" disabled>Select template</option>{#each templates as item}<option value={item.id}>{item.name}</option>{/each}</select></label><label class="full">Date<input type="date" bind:value={session.sessionDateUtc} required /></label><div class="full"><button class="button">Create session</button></div></form><h3>Today’s sessions</h3>{#each sessions as item}<article class="announcement"><strong>{item.name}</strong><br /><span>{item.startTime} · {item.durationMinutes} minutes</span></article>{:else}<p class="muted">No sessions today.</p>{/each}</section></div>
